def transform(grid):
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    marker = next(v for row in grid for v in row if v != bg)
    fill = (marker + 1) % 10
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if row[c] == bg:
                    out[r][c] = fill
    return out
